# ספר הזכרונות ח"ב — חילוץ גוף הטקסט לכל עמוד (pages/NNN.txt) לפני הגהה
import re, json, difflib, os
P = re.sub(r'[‪-‮]', '', open('zich.txt', encoding='utf-8').read()).split('\f')
OFF = 6   # עמוד בספר = עמוד PDF פחות 6
CH = [(7, 'סב', 'הפרוש מדוברובנה'), (12, 'סג', 'עונשו של אכזר'), (16, 'סד', 'אב ובן'), (21, 'סה', 'ר׳ פסח הצרפתי'), (26, 'סו', 'התרופה של הבעל־שם־טוב'), (31, 'סז', 'הצעיר השתקן'), (36, 'סח', 'תורה ועבודה'), (41, 'סט', 'הרב ותלמידו'), (45, 'ע', 'דרכו החדשה של ברוך מוויאזין'), (49, 'עא', 'אדם ותבל'), (53, 'עב', 'ברוך בונה בית'), (57, 'עג', 'הקנאים הסלוצקאים'), (61, 'עד', 'רבי אדם בעל־שם'), (65, 'עה', 'חמומי המוח בסלוצק'), (69, 'עו', 'העילוי המסתורי'), (74, 'עז', 'יהודי השונא דרשנים'), (78, 'עח', 'הבעש״ט מקבל את ההנהגה'), (83, 'עט', 'הבעש״ט בסלוצק'), (87, 'פ', 'אשה למדנית ובתה'), (92, 'פא', 'סגולתו של הבעל־שם'), (97, 'פב', '״דין תורה״ מעניין'), (101, 'פג', 'מהר״ל מפראג'), (106, 'פד', 'הכהן והגרושה'), (110, 'פה', 'סופו של חטא'), (113, 'פו', 'משפחת מהר״ל'), (117, 'פז', 'חכמה יהודית ושנאה גויית'), (122, 'פח', 'המהר״ל והנסיך'), (129, 'פט', 'ההסתה נגד יהודים'), (133, 'צ', 'השבועה נגד השמד'), (137, 'צא', 'ביטול הגזירה'), (141, 'צב', 'נצחונו של המהר״ל'), (148, 'צג', 'למדנות האם והבת'), (156, 'צד', '״תנאים״ בבית העלמין'), (160, 'צה', 'רבם של עמי הארץ'), (165, 'צו', '״משיח אלמים״'), (170, 'צז', 'המשכון החי'), (174, 'צח', 'תורה ועבודה'), (178, 'צט', 'רבי ישראל בעל־שם־טוב'), (183, 'ק', 'מינסק'), (186, 'קא', 'ועד ארבע הארצות'), (191, 'קב', 'השידוך המזומן'), (197, 'קג', 'רדיפות'), (201, 'קד', 'רוח הקודש של הבעש״ט'), (205, 'קה', 'מיגון לשמחה'), (208, 'קו', 'סודות הקבלה'), (212, 'קז', 'מקבלה לחסידות'), (215, 'קח', 'תורה וגדולה'), (219, 'קט', 'הויכוח עם הוותיקן'), (223, 'קי', 'על פי התהום'), (227, 'קיא', 'הנצחון היהודי'), (231, 'קיב', 'ה״נזיר״ ברומא'), (235, 'קיג', 'גר הצדק'), (240, 'קיד', 'גלגוליו של ר׳ משה'), (245, 'קטו', 'הסב ונכדיו'), (249, 'קטז', 'הבלן ממינסק ובנו'), (253, 'קיז', 'השמש ובתו היחידה'), (257, 'קיח', 'מבלנות לרבנות'), (262, 'קיט', 'מקום בגן עדן'), (266, 'קכ', 'מושבה של מקובלים'), (270, 'קכא', 'אהבה לילדים'), (274, 'קכב', 'התנאי של הצדיק'), (279, 'קכג', 'ילד הפלא'), (283, 'קכד', 'הרב ותלמידיו'), (287, 'קכה', 'היהודי האמיץ'), (292, 'קכו', 'שני שידוכים'), (296, 'קכז', 'שליחו של הבעל־שם'), (300, 'קכח', 'צרות צבוריות ופרטיות'), (304, 'קכט', 'טובתם ורשעתם של גויים'), (309, 'קל', 'יהודים עוזבים את פוזנא'), (313, 'קלא', 'תורה ומלאכה'), (317, 'קלב', 'היתומה'), (321, 'קלג', 'השידוך'), (325, 'קלד', 'האוצר'), (329, 'קלה', 'הישיבה של גולדה לאה'), (333, 'קלו', 'הנצחון על פינסק המתנגדית'), (337, 'קלז', 'במהלך הדורות')]
LAST = 339
def chap(pg): return max(i for i, c in enumerate(CH) if c[0] <= pg)
def sim(a, b): return difflib.SequenceMatcher(None, re.sub(r'\W', '', a), re.sub(r'\W', '', b)).ratio()
def fixline(s):
    s = s.translate(str.maketrans('()', ')('))
    s = re.sub(r'\s+([.,:;!?])(?=\S)', r'\1 ', s)
    s = re.sub(r'\s+([.,:;!?])\s*$', r'\1', s)
    s = re.sub(r'\s+-\s*|\s*-\s+', ' — ', s)
    return re.sub(r'\s{2,}', ' ', s).strip()
os.makedirs('pages', exist_ok=True)
pagechap = {}
for pg in range(7, LAST + 1):
    ci = chap(pg); title = CH[ci][2]; pagechap[pg] = ci
    L = [l.strip() for l in P[pg - 1].split('\n') if l.strip()]
    out = []
    for k, s in enumerate(L):
        if s.startswith('*'): break                       # הערות שוליים בתחתית
        if k < 4:
            if re.fullmatch(r'[\d I\.י]{1,8}', s) or re.match(r'^ספר הז.{0,3}רו.{0,2}ת$', s): continue
            if len(s.split()) <= 9 and sim(s, title) > 0.6: continue
            if CH[ci][0] == pg and re.match(r'^פרק', s): continue
            if pg >= 342 and s == 'הוספות והערות': continue
        out.append(fixline(s))
    open('pages/%03d.txt' % pg, 'w', encoding='utf-8').write('\n'.join(out) + '\n')
json.dump({'CH': CH, 'OFF': OFF, 'LAST': LAST}, open('struct.json', 'w'), ensure_ascii=False)
print('ok')
